css:
@import url("https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@600;800;900&family=Libre+Franklin:wght@400;500;700&display=swap");
:root{--co:#2340FF;--co2:#1A30C4;--ch:#F3F2EE;--cn:#CFCBC4;--bk:#141414;--gr:#55524C;--h:"Big Shoulders Display",Impact,sans-serif;--b:"Libre Franklin",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.6;color:var(--bk);background:var(--ch)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:800;margin:0;line-height:.95;text-transform:uppercase}
.wrap{max-width:1200px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--co);outline-offset:3px}
.hero{position:relative;min-height:720px;color:#fff;display:flex;flex-direction:column;background:var(--bk)}
.hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.6}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(20,20,20,.85),rgba(20,20,20,.2) 70%)}
.nav{position:relative;z-index:5;display:flex;justify-content:space-between;align-items:center;height:84px}
.logo{font-family:var(--h);font-weight:900;font-size:30px;text-decoration:none;letter-spacing:.02em}.logo span{color:#8FA0FF}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:#8FA0FF}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;font-size:20px;cursor:pointer}
.hc{position:relative;z-index:3;flex:1;display:flex;flex-direction:column;justify-content:flex-end;padding-bottom:60px}
.hero h1{font-size:clamp(70px,13vw,190px);font-weight:900;line-height:.82;letter-spacing:-.01em}.hero h1 span{display:block;-webkit-text-stroke:2px #fff;color:transparent}
.hero p{max-width:30em;font-size:19px;margin:26px 0 26px;color:#E6E6E6}
.btn{display:inline-block;background:var(--co);color:#fff;font:700 16px var(--b);text-decoration:none;padding:16px 28px;border:0;cursor:pointer}.btn.w{background:#fff;color:var(--bk)}
.row{display:flex;gap:12px;flex-wrap:wrap}
.band{background:var(--co);color:#fff;overflow:hidden}.band .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px 30px;padding-top:18px;padding-bottom:18px;font-family:var(--h);font-weight:800;font-size:26px;text-transform:uppercase}
section{padding:90px 0}.sh{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;flex-wrap:wrap;margin-bottom:32px}.sh h2{font-size:clamp(46px,6vw,84px)}.sh p{max-width:28em;margin:0;color:var(--gr)}
.days{display:flex;flex-wrap:wrap;border:2px solid var(--bk);margin-bottom:0}.days button{flex:1 1 0;min-width:70px;font:800 22px var(--h);text-transform:uppercase;background:transparent;border:0;border-right:2px solid var(--bk);padding:14px 6px;cursor:pointer;color:var(--bk)}.days button:last-child{border-right:0}
.days button[aria-pressed=true]{background:var(--bk);color:#fff}
.tt{border:2px solid var(--bk);border-top:0;background:#fff}
.cl{display:grid;grid-template-columns:110px 1fr 160px 150px 130px;align-items:center;gap:16px;padding:18px 22px;border-bottom:1px solid var(--cn)}.cl:last-child{border-bottom:0}
.cl .t{font-family:var(--h);font-size:30px;font-weight:800}.cl h3{font-size:28px}.cl small{display:block;color:var(--gr);font-size:15px}
.lv{display:flex;gap:4px;align-items:center;font-size:14px;color:var(--gr)}.lv i{width:10px;height:22px;background:var(--cn)}.lv i.on{background:var(--co)}
.sp{font-size:15px;font-weight:700}.sp.low{color:#C8341F}
.cl button{font:700 15px var(--b);background:var(--bk);color:#fff;border:0;padding:12px;cursor:pointer}.cl button[aria-pressed=true]{background:var(--co)}.cl button:disabled{background:var(--cn);color:var(--gr);cursor:not-allowed}
.plans{background:var(--bk);color:#fff}.plans .sh p{color:#B5B5B5}
.tog{display:inline-flex;border:2px solid #fff}.tog button{font:700 15px var(--b);background:transparent;color:#fff;border:0;padding:10px 18px;cursor:pointer}.tog button[aria-pressed=true]{background:#fff;color:var(--bk)}
.pg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border:2px solid #333}
.pl{padding:34px 30px;border-right:2px solid #333;display:flex;flex-direction:column}.pl:last-child{border-right:0}.pl.hot{background:var(--co)}
.pl h3{font-size:38px}.pl .pr{font-family:var(--h);font-size:84px;font-weight:900;line-height:1;margin:18px 0 4px}.pl .pr small{font-size:22px}.pl .note{color:#C9C9C9;font-size:15px;min-height:24px}.pl.hot .note{color:#DDE2FF}
.pl ul{list-style:none;padding:0;margin:22px 0 28px;flex:1}.pl li{padding:8px 0;border-bottom:1px solid rgba(255,255,255,.15)}.pl li:before{content:"+ ";font-weight:700;color:#8FA0FF}.pl.hot li:before{color:#fff}
.pl .btn{text-align:center}.pl.hot .btn{background:#fff;color:var(--bk)}
.bmi .wrap{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.bmi form{background:#fff;border:2px solid var(--bk);padding:30px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:16px}.fr>div{min-width:0}
label{display:block;font-weight:700;font-size:15px;margin-bottom:6px}input,select{width:100%;font:18px var(--b);padding:12px;border:2px solid var(--cn);background:#fff;margin-bottom:16px;color:var(--bk)}
.res{margin-top:6px}.res b{font-family:var(--h);font-size:72px;font-weight:900;line-height:1}.res p{margin:4px 0 16px}
.scale{position:relative;height:18px;display:grid;grid-template-columns:8.5fr 6.5fr 5fr 10fr}.scale i:nth-child(1){background:#8FC7FF}.scale i:nth-child(2){background:#3CB371}.scale i:nth-child(3){background:#F2B632}.scale i:nth-child(4){background:#E0603A}
.mk{position:absolute;top:-8px;width:4px;height:34px;background:var(--bk);transform:translateX(-2px);transition:left .3s}.lg{display:flex;justify-content:space-between;font-size:13px;color:var(--gr);margin-top:8px}
.coach{background:#fff}.cg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.co img{width:100%;aspect-ratio:4/5;object-fit:cover;filter:grayscale(1) contrast(1.05)}.co:hover img{filter:none}
.co h3{font-size:34px;margin-top:14px}.co p{margin:6px 0 0;color:var(--gr)}
footer{background:var(--bk);color:#BDBDBD;padding:40px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.cl{grid-template-columns:90px 1fr 130px;}.cl .lv{display:none}.pg,.cg{grid-template-columns:1fr}.pl{border-right:0;border-bottom:2px solid #333}.bmi .wrap{grid-template-columns:1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:84px;left:0;right:0;background:var(--bk);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.hero{min-height:620px}
.cl{grid-template-columns:1fr auto;gap:6px 12px}.cl .t{font-size:24px}.cl>div:nth-child(2){grid-column:1/-1;order:-1}.cl button{grid-column:1/-1}.days button{min-width:25%;border-bottom:2px solid var(--bk)}.fr{grid-template-columns:1fr}.cg{grid-template-columns:1fr 1fr}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const D=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
const C=[["06:00","HIIT Burn","Jo",3,14],["07:15","Barbell Basics","Marcus",2,12],["12:30","Lunch Express (30 min)","Priya",2,16],["17:30","Strength Circuit","Marcus",3,14],["18:45","Mobility Flow","Priya",1,18],["19:30","Boxing Fit","Jo",3,16]];
const tt={};D.forEach((d,i)=>{tt[d]=C.filter((c,j)=>(i+j)%6!==0||i===5).slice(0,i>4?4:5).map((c,j)=>({t:i>4?["08:00","09:30","11:00","12:30"][j]:c[0],n:c[1],c:c[2],lv:c[3],left:(i*3+j*5)%9,b:false}))});
let day=D[(new Date().getDay()+6)%7];
function draw(){$('days').innerHTML=D.map(d=>`<button type="button" aria-pressed="${d===day}">${d}</button>`).join('');
$('tt').innerHTML=tt[day].map((c,i)=>`<div class="cl"><span class="t">${c.t}</span><div><h3>${c.n}</h3><small>with ${c.c}</small></div><span class="lv" aria-label="Intensity ${c.lv} of 3">${[1,2,3].map(n=>`<i class="${n<=c.lv?'on':''}"></i>`).join('')} ${['','Easy','Medium','Hard'][c.lv]}</span><span class="sp ${c.left<3?'low':''}">${c.left?c.left+' spots left':'Full, join waitlist'}</span><button type="button" data-i="${i}" aria-pressed="${c.b}" ${!c.left&&!c.b?'':''}>${c.b?'Booked ✓':c.left?'Book':'Waitlist'}</button></div>`).join('')}
$('days').onclick=e=>{const b=e.target.closest('button');if(!b)return;day=b.textContent;draw()};
$('tt').onclick=e=>{const b=e.target.closest('button');if(!b)return;const c=tt[day][b.dataset.i];if(c.b){c.b=false;c.left++}else{c.b=true;if(c.left)c.left--}draw()};draw();
document.querySelector('.tog').onclick=e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('.tog button').forEach(x=>x.setAttribute('aria-pressed',x===b));const y=b.dataset.b==='y';
document.querySelectorAll('.pl').forEach(p=>{const pr=p.querySelector('.pr');pr.innerHTML=y?`£${pr.dataset.y}<small>/yr</small>`:`£${pr.dataset.m}<small>/mo</small>`;p.querySelector('.note').textContent=y?`That's £${(pr.dataset.y/12).toFixed(2)} a month, paid once a year.`:''})};
function bmi(){const h=+$('hgt').value/100,w=+$('wgt').value;if(!h||!w)return;const v=w/(h*h);$('bv').textContent=v.toFixed(1);
const [t,m]=v<18.5?['Below the healthy range. A coach can help you build strength and weight safely.','under']:v<25?['In the healthy range. Nice. Keep training and eating well.','ok']:v<30?['A little above the healthy range. Regular training and small food changes make a real difference.','over']:['Above the healthy range. Talk to your GP, and we can build a gentle plan together.','high'];
$('bt').textContent=t;$('mk').style.left=Math.min(100,Math.max(0,(v-10)/30*100))+'%'}
['hgt','wgt'].forEach(i=>$(i).addEventListener('input',bmi));$('bf').onsubmit=e=>e.preventDefault();bmi();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
